`timescale 1ns / 1ps

// Direct digital synthesiser (numerically controlled oscillator).
//
// A 32-bit phase accumulator advances by phase_inc on every enabled clock.
// Its top 10 bits address a 1024-entry sine table (sine_lut.mem, 16-bit
// values, generated by python/generate_tables.py).
//
//   output frequency = phase_inc / 2^32 * sample rate
//
//   i_out = cos(phase)      q_out = sin(phase)

module dds_iq_source #(
    parameter PHASE_W = 32,
    parameter DATA_W  = 16
)(
    input wire                     clk,
    input wire                     rst,

    input wire                     enable,
    input wire                     ready,       // not used; kept for compatibility

    input wire [PHASE_W-1:0]       phase_inc,

    output wire signed [DATA_W-1:0] i_out,
    output wire signed [DATA_W-1:0] q_out,
    output wire                      valid
);

    reg [PHASE_W-1:0] phase;

    // ------------------------------------------------------------
    // Sine table
    // ------------------------------------------------------------

    reg signed [15:0] sine_lut [0:1023];

    initial begin
        $readmemh("sine_lut.mem", sine_lut);
    end

    wire [9:0] sin_addr = phase[PHASE_W-1 -: 10];
    wire [9:0] cos_addr = sin_addr + 10'd256;      // a quarter turn ahead

    assign i_out = sine_lut[cos_addr];
    assign q_out = sine_lut[sin_addr];

    // A sample is valid whenever the DDS is enabled.
    assign valid = enable;

    // ------------------------------------------------------------
    // Phase accumulator
    // ------------------------------------------------------------

    always @(posedge clk) begin
        if (rst) begin
            phase <= {PHASE_W{1'b0}};
        end
        else if (enable) begin
            phase <= phase + phase_inc;
        end
    end

endmodule
